import { Link } from "react-router-dom";
import React, { useEffect, useState } from "react";
import PropTypes from "prop-types";
import { getAllCars, deleteCarById } from "../../services/ApiCar";

export default function CardVoiture({ color }) {
  const [Cars, setCars] = useState([]);

  const getcars = async () => {
    try {
      const res = await getAllCars();
      setCars(res.data);
    } catch (error) {
      console.log(error);
    }
  };

  const deleteCar = async (id) => {
    try {
      await deleteCarById(id);
      getcars();
    } catch (error) {
      console.log(error);
    }
  };

  useEffect(() => {
    getcars();
  }, []);

  return (
    <>
      <div className="mb-4">
        <Link to="/admin/AddVoiture">
          <button className="bg-emerald-500 hover:bg-emerald-600 text-white font-bold py-2 px-4 rounded-lg shadow-md transition-colors duration-200">
            ➕ Add New Car
          </button>
        </Link>
      </div>
      <div className={`relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg ${color === "light" ? "bg-white" : "bg-lightBlue-900 text-white"}`}>
        <div className="rounded-t-lg mb-0 px-4 py-3 border-0">
          <div className="flex flex-wrap items-center">
            <div className="relative w-full px-4 max-w-full flex-grow flex-1">
              <h3 className={`font-semibold text-lg ${color === "light" ? "text-blueGray-700" : "text-white"}`}>
                Voiture Tables
              </h3>
            </div>
          </div>
        </div>
        <div className="block w-full overflow-x-auto">
          <table className="items-center w-full bg-transparent border-collapse">
            <thead>
              <tr>
                <th className="px-6 py-3 text-left text-xs font-semibold text-blueGray-500 uppercase tracking-wider">Model</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-blueGray-500 uppercase tracking-wider">Matricule</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-blueGray-500 uppercase tracking-wider">Prix</th>
                <th className="px-6 py-3 text-left text-xs font-semibold text-blueGray-500 uppercase tracking-wider">CreatedAt</th>
                <th className="px-6 py-3 text-center text-xs font-semibold text-blueGray-500 uppercase tracking-wider">Actions</th>
              </tr>
            </thead>
            <tbody>
              {Cars.map((car, index) => (
                <tr key={index} className={index % 2 === 0 ? "bg-blueGray-50" : "bg-white"}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-blueGray-800">{car.model}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-blueGray-800">{car.matricule}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-blueGray-800">{car.prix}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-blueGray-800">
                    {new Date(car.createdAt).toLocaleString()}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                    <div className="flex justify-center space-x-2">
                      <Link to={`/admin/update-voiture/${car._id}`} className="text-blue-500 hover:text-blue-700">
                        ✓ Update
                      </Link>
                      <button 
                        onClick={() => deleteCar(car._id)} 
                        className="text-red-500 hover:text-red-700"
                      >
                        ☑ Delete
                      </button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </>
  );
}

CardVoiture.defaultProps = {
  color: "light",
};

CardVoiture.propTypes = {
  color: PropTypes.oneOf(["light", "dark"]),
};
